entries[23059] = { ["name"] = "Ring of the Dreadnaught", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+3 Stamina\n+ 3 Dodge\nClasses: Warrior\nDreadnaught's Battlegear (0/9)\nDreadnaught Bracers\nDreadnaught Breastplate\nDreadnaught Gauntlets\nDreadnaught Waistguard\nDreadnaught Helmet\nDreadnaught Legplates\nDreadnaught Pauldrons\nDreadnaught Sabatons\nRing of the Dreadnaught\nLegacy Set: Bonus is inactive\n(2) Set : Increases the damage done by your Revenge ability by 75.\n(4) Set : Improves your critical strike chance by 3%.\n(6) Set : Increases your chance to Parry by 5%.\n(8) Set : When your health drops below 20%, for the next 5 seconds healing spells cast on you help you to Cheat Death, increasing healing done to you by up to 160.\nSell Price:" }
entries[23060] = { ["name"] = "Bonescythe Ring", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+2 Strength\n+2 Agility\n+3 Stamina\n+ 2 Haste\nClasses: Rogue\nBonescythe Armor (0/9)\nBonescythe Bracers\nBonescythe Breastplate\nBonescythe Gauntlets\nBonescythe Helmet\nBonescythe Legplates\nBonescythe Pauldrons\nBonescythe Sabatons\nBonescythe Waistguard\nBonescythe Ring\nLegacy Set: Bonus is inactive\n(2) Set : Your normal melee swings have a chance to Invigorate you, healing you for 100.\n(4) Set : Your Backstab, Mutilate, Dispatch, Sinister Strike, and Hemorrhage critical hits cause you to regain 5 energy.\n(6) Set : Reduces the threat from your Backstab, Sinister Strike, Hemorrhage, and Eviscerate abilities.\n(8) Set : Your Eviscerate and Envenom have a chance per combo point to reveal a flaw in your opponent's armor, granting a 100% critical hit chance for your next Backstab, Sinister Strike, Dispatch, or Hemorrhage.\nSell Price:" }
entries[23061] = { ["name"] = "Ring of Faith", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+3 Intellect\n+3 Stamina\n+ 3 Versatility\nClasses: Priest\nVestments of Faith (0/9)\nBelt of Faith\nBindings of Faith\nCirclet of Faith\nGloves of Faith\nLeggings of Faith\nRobe of Faith\nSandals of Faith\nShoulderpads of Faith\nRing of Faith\nLegacy Set: Bonus is inactive\n(2) Set : Intellect increased by 20.\n(4) Set : On Heal critical hits, your target will gain Armor of Faith, absorbing up to 500 damage.\n(6) Set : Reduces the threat from your healing spells.\n(8) Set : Each spell you cast can trigger an Epiphany, increasing your Versatility by 60 for 30 sec. (Proc chance: 5%)\nSell Price:" }
entries[23062] = { ["name"] = "Frostfire Ring", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+3 Intellect\n+3 Stamina\n+ 2 Critical Strike\nClasses: Mage\nFrostfire Regalia (0/9)\nFrostfire Belt\nFrostfire Bindings\nFrostfire Circlet\nFrostfire Gloves\nFrostfire Leggings\nFrostfire Robe\nFrostfire Sandals\nFrostfire Shoulderpads\nFrostfire Ring\nLegacy Set: Bonus is inactive\n(2) Set : Reduces cooldown on your Evocation by 0 minute.\n(4) Set : Increases intellect by 20.\n(6) Set : Your damage spells have a chance to cause your target to take up to 200 increased damage from subsequent spells. (Proc chance: 20%)\n(8) Set : Your damage spells have a chance to displace you, causing the next spell cast to generate no threat. (Proc chance: 15%)\nSell Price:" }
entries[23063] = { ["name"] = "Plagueheart Ring", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+3 Intellect\n+3 Stamina\nClasses: Warlock\nPlagueheart Raiment (0/9)\nPlagueheart Belt\nPlagueheart Bindings\nPlagueheart Circlet\nPlagueheart Gloves\nPlagueheart Leggings\nPlagueheart Robe\nPlagueheart Sandals\nPlagueheart Shoulderpads\nPlagueheart Ring\nLegacy Set: Bonus is inactive\n(2) Set : Your Shadow Bolts, Haunts, and Incinerates now have a chance to heal you for 300.\n(4) Set : Increases damage caused by your Corruption and Immolate by 12%.\n(6) Set : Your spells generate 25% less threat. In addition, Corruption, Immolate, Curse of Agony, and Siphon Life further generate 25% less threat.\n(8) Set : Haste increased by 5%.\nSell Price:" }
entries[23064] = { ["name"] = "Ring of the Dreamwalker", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+2 Intellect\n+3 Stamina\n+ 3 Versatility\nClasses: Druid\nDreamwalker Raiment (0/9)\nDreamwalker Boots\nDreamwalker Girdle\nDreamwalker Handguards\nDreamwalker Headpiece\nDreamwalker Legguards\nDreamwalker Spaulders\nDreamwalker Tunic\nDreamwalker Wristguards\nRing of the Dreamwalker\nLegacy Set: Bonus is inactive\n(2) Set : Increases the healing of Rejuvenation by 2%.\n(4) Set : Reduces the mana cost of your Healing Touch, Regrowth, Rejuvenation, and Tranquility spells by 3%.\n(6) Set : Your initial cast and Regrowth ticks will increase the maximum health of your target by up to 50, stacking up to 7 times.\n(8) Set : On Healing Touch and Regrowth critical hits, you regain 30% of the mana cost of the spell.\nSell Price:" }
entries[23065] = { ["name"] = "Ring of the Earthshatterer", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+2 Intellect\n+3 Stamina\n+ 3 Versatility\nClasses: Shaman\nThe Earthshatterer (0/9)\nEarthshatter Boots\nEarthshatter Girdle\nEarthshatter Handguards\nEarthshatter Headpiece\nEarthshatter Legguards\nEarthshatter Spaulders\nEarthshatter Tunic\nEarthshatter Wristguards\nRing of the Earthshatterer\nLegacy Set: Bonus is inactive\n(2) Set : Reduces the mana cost of your totem spells by 12%.\n(4) Set : Increases critical strike chance by 3%.\n(6) Set : Your Healing Wave and Healing Surge spells have a chance to imbue your target with Totemic Power. (Proc chance: 10%)\n(8) Set : Your Lightning Shield spell also grants you 38 Intellect while active.\nSell Price:" }
entries[23066] = { ["name"] = "Ring of Redemption", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+2 Intellect\n+3 Stamina\n+ 3 Versatility\nClasses: Paladin\nRedemption Armor (0/9)\nRedemption Boots\nRedemption Girdle\nRedemption Handguards\nRedemption Headpiece\nRedemption Legguards\nRedemption Spaulders\nRedemption Tunic\nRedemption Wristguards\nRing of Redemption\nLegacy Set: Bonus is inactive\n(2) Set : Increases the damage of Judgment by 15%.\n(4) Set : Reduces cooldown on your Lay on Hands by 4 min.\n(6) Set : Your Flash of Light and Holy Light spells have a chance to imbue your target with Holy Power. (Proc chance: 10%)\n(8) Set : Your Cleanse spell also heals the target for 200.\nSell Price:" }
entries[23067] = { ["name"] = "Ring of the Cryptstalker", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+2 Agility\n+3 Stamina\n+ 3 Critical Strike\nClasses: Hunter\nCryptstalker Armor (0/9)\nCryptstalker Boots\nCryptstalker Girdle\nCryptstalker Handguards\nCryptstalker Headpiece\nCryptstalker Legguards\nCryptstalker Spaulders\nCryptstalker Tunic\nCryptstalker Wristguards\nRing of the Cryptstalker\nLegacy Set: Bonus is inactive\n(2) Set : Increases your Critical Strike by 30.\n(4) Set : While your pet is active, increases attack power by 50 for both you and your pet.\n(6) Set : Your ranged critical hits cause an Adrenaline Rush, granting you 5 Focus\n(8) Set : Reduces the Focus cost of your Multi-Shot and Aimed Shot by 20.\nSell Price:" }
