entries[23618] = { ["name"] = "Plans: Adamantite Sharpening Stone", ["text"] = "Binds when picked up\nUse: Teaches you how to make an Adamantite Sharpening Stone.\nRequires Outland Blacksmithing (50)\nRequires Cenarion Expedition\n- Honored\nSell Price:\nAdamantite Sharpening Stone\nUse: Sharpens your bladed weapon, increasing weapon damage by 4 and critical strike by 4 for 1 hour. Cannot be applied to items higher than level 320.\nSell Price:\nRequires Adamantite Bar , Mote of Earth (2)" }
